import{_ as a,o as n,c as s,a5 as r}from"./chunks/framework.R-FQ1xZ2.js";const h=JSON.parse('{"title":"知识体系总览","description":"","frontmatter":{"title":"知识体系总览","order":0},"headers":[],"relativePath":"kb/index.md","filePath":"kb/index.md","lastUpdated":null}'),d={name:"kb/index.md"};function e(l,t,o,i,p,c){return n(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="知识体系总览" tabindex="-1">知识体系总览 <a class="header-anchor" href="#知识体系总览" aria-label="Permalink to &quot;知识体系总览&quot;">​</a></h1><p>这一套知识体系是我从 <strong>20 个来源</strong>（Datawhale 8 个主干仓库 + LangChain / LangGraph / MCP / Anthropic / Ragas / vLLM / HF / LLaMA-Factory / ms-swift / Dify / openai-cookbook 等官方文档）逐一读目录、读章节后，按「一个知识点 = 一个页面」的方式重新组织的。不是搜索结果的堆砌，每个知识点都写清了「是什么 / 为什么必须学 / 面试考不考 / 要花多少学时」。</p><p><strong>总量</strong>：L0 底座层 30 项 + L1–L7 共 <strong>155 个知识点</strong>。</p><hr><h2 id="一、分层地图" tabindex="-1">一、分层地图 <a class="header-anchor" href="#一、分层地图" aria-label="Permalink to &quot;一、分层地图&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  编程与工程基础             30 项   Python / Git / Linux / 数据结构 / 后端 API / 前端最小可用</span></span>
<span class="line"><span>                                     ↓ 底座，不在 155 计数内，但面试与工程实践全程依赖</span></span>
<span class="line"><span>L1  大模型原理                 24 项   Transformer / 注意力 / Tokenizer / 位置编码 / 推理机制 / 训练三阶段</span></span>
<span class="line"><span>                                     ↓ 不懂原理 → 无法解释 RAG 为什么失效、Agent 为什么会绕圈</span></span>
<span class="line"><span>L2  提示工程与结构化输出       22 项   Prompt 设计 / Few-shot / CoT / 结构化输出 / 工具调用协议 / 上下文工程</span></span>
<span class="line"><span>                                     ↓ Agent 的最小单元就是「一次可控的模型调用」</span></span>
<span class="line"><span>L3  RAG 与检索                 28 项   数据加载 / 切块 / Embedding / 向量库 / 混合检索 / Rerank / 查询改写 / GraphRAG</span></span>
<span class="line"><span>                                     ↓ 企业 AI 应用需求量最大的落点</span></span>
<span class="line"><span>L4  Agent 与工具生态           33 项   ReAct / 规划 / 记忆 / 多智能体 / LangGraph / MCP / 沙箱 / 人机确认</span></span>
<span class="line"><span>                                     ↓ 岗位名字里的那个词</span></span>
<span class="line"><span>L5  工程化与服务部署           24 项   流式 / 并发 / 限流 / 缓存 / 容器 / vLLM / 量化 / 观测 / 成本</span></span>
<span class="line"><span>                                     ↓ 决定你的项目是「demo」还是「系统」</span></span>
<span class="line"><span>L6  评测与可观测               14 项   评测集构建 / LLM-as-judge / Ragas 指标 / 回归门禁 / Trace / 线上监控</span></span>
<span class="line"><span>                                     ↓ 唯一能证明「我的改动让系统变好了」的能力</span></span>
<span class="line"><span>L7  进阶：微调 / 推理优化 / 多模态  10 项  SFT / LoRA / QLoRA / DPO / GRPO / 蒸馏 / 推理优化 / VLM</span></span>
<span class="line"><span>                                     ↓ 拉开与「只会调 API」候选人差距的部分</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h2 id="二、计数表与面试权重" tabindex="-1">二、计数表与面试权重 <a class="header-anchor" href="#二、计数表与面试权重" aria-label="Permalink to &quot;二、计数表与面试权重&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>主题</th><th>知识点数</th><th>面试权重</th><th>说明</th></tr></thead><tbody><tr><td>L0</td><td>编程与工程基础</td><td>30</td><td>中</td><td>编码面必考，但不区分度</td></tr><tr><td>L1</td><td>大模型原理</td><td>24</td><td>高</td><td>决定你能不能解释上层现象</td></tr><tr><td>L2</td><td>提示工程与结构化输出</td><td>22</td><td>高</td><td>面试官 15 分钟就能问到底</td></tr><tr><td>L3</td><td>RAG 与检索</td><td>28</td><td><strong>最高</strong></td><td>我的两个项目主线，必被深挖</td></tr><tr><td>L4</td><td>Agent 与工具生态</td><td>33</td><td><strong>最高</strong></td><td>岗位名字里的词</td></tr><tr><td>L5</td><td>工程化与服务部署</td><td>24</td><td>中高</td><td>决定「demo」还是「系统」</td></tr><tr><td>L6</td><td>评测与可观测</td><td>14</td><td>中高</td><td>应届生最容易被问倒</td></tr><tr><td>L7</td><td>进阶：微调 / 推理优化 / 多模态</td><td>10</td><td>中（大模型开发岗为高）</td><td>拉开差距</td></tr><tr><td>—</td><td><strong>L1–L7 合计</strong></td><td><strong>155</strong></td><td>—</td><td>—</td></tr></tbody></table><h2 id="三、时间不够时按这个顺序砍" tabindex="-1">三、时间不够时按这个顺序砍 <a class="header-anchor" href="#三、时间不够时按这个顺序砍" aria-label="Permalink to &quot;三、时间不够时按这个顺序砍&quot;">​</a></h2><ol><li><strong>L4 Agent 与工具生态</strong> —— 岗位名的来源，也是我 YYHelp 项目的主战场（LangGraph 状态图、ReAct 循环、工具契约、长期记忆、MCP）。面试官会按「你做过什么」深挖，这一层答不上来直接崩。</li><li><strong>L3 RAG 与检索</strong> —— 企业需求量最大，我的两个项目都在这。会被连问三层：切片策略 → 为什么这样切 → 评测集多少条怎么构造。</li><li><strong>L6 评测与可观测</strong> —— 大多应届生答不出「你怎么证明改了以后变好了」。我在 YYHelp 里做了配对 t 检验 + Holm 校正 + 三态退出码的回归门禁，这是我的差异化点，必须能讲透。</li><li><strong>L1 大模型原理</strong> —— 会被问 Transformer / Attention / KV Cache / GQA / 位置编码。答不出「显存怎么算」会被判定为只会调 API。</li><li><strong>L2 提示工程</strong> —— 看起来简单，但「结构化输出四条路线各自保证什么」能筛掉大部分人。</li><li><strong>L5 工程化</strong> —— 流式、并发、限流、缓存、容器、成本归因。</li><li><strong>L7 进阶</strong> —— 大模型开发岗要，Agent / 应用岗可以后置。</li></ol><h2 id="四、每一页都长一个样" tabindex="-1">四、每一页都长一个样 <a class="header-anchor" href="#四、每一页都长一个样" aria-label="Permalink to &quot;四、每一页都长一个样&quot;">​</a></h2><p>跳着读也不会断：</p><table tabindex="0"><thead><tr><th>小节</th><th>作用</th></tr></thead><tbody><tr><td><strong>一句话说清</strong></td><td>30 秒建立印象，先看这个</td></tr><tr><td><strong>为什么必须学</strong></td><td>面试官视角：不学这个会挂在哪</td></tr><tr><td><strong>核心内容</strong></td><td>定义 / 机制 / 为什么这样设计 / 数量级与形状 / 常见误区 / 代码</td></tr><tr><td><strong>图示</strong></td><td>Mermaid 流程图，能画出来的都用图</td></tr><tr><td><strong>和你自己的项目对上号</strong></td><td>这个知识点落在我 YYHelp / RAG 项目的哪个模块</td></tr><tr><td><strong>面试怎么问</strong></td><td>≥3 组 Q/A，含追问链</td></tr><tr><td><strong>自检清单</strong></td><td>能答上来才算过关</td></tr><tr><td><strong>相关</strong></td><td>交叉引用的其他页面</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">配合架构图库看</p><p>知识体系讲「为什么」，<a href="/learn/diagrams/">架构图库</a> 讲「长什么样」。同一主题两边都有时，先看图建立空间感，再回来看文字，效率最高。</p></div><h2 id="五、按层的入口" tabindex="-1">五、按层的入口 <a class="header-anchor" href="#五、按层的入口" aria-label="Permalink to &quot;五、按层的入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>入口</th><th>主题</th></tr></thead><tbody><tr><td>L0</td><td><a href="/learn/kb/l0-foundation/">L0 · 编程与工程基础</a></td><td>Python 类型系统 / 异步 / Git / Linux / SQL / 后端 API / 前端最小可用</td></tr><tr><td>L1</td><td><a href="/learn/kb/l1-llm/">L1 · 大模型原理</a></td><td>Transformer / 注意力 / Tokenizer / 位置编码 / KV Cache / 解码 / 训练三阶段</td></tr><tr><td>L2</td><td><a href="/learn/kb/l2-prompt/">L2 · 提示工程与结构化输出</a></td><td>Prompt 设计 / CoT / 结构化输出 / Function Calling / 注入防护 / 上下文工程</td></tr><tr><td>L3</td><td><a href="/learn/kb/l3-rag/">L3 · RAG 与检索</a></td><td>加载 / 切块 / Embedding / 向量索引 / 混合检索 / RRF / Rerank / 查询改写 / 评测</td></tr><tr><td>L4</td><td><a href="/learn/kb/l4-agent/">L4 · Agent 与工具生态</a></td><td>ReAct / 规划 / 记忆 / 多智能体 / LangGraph / MCP / 沙箱 / 人机确认</td></tr><tr><td>L5</td><td><a href="/learn/kb/l5-engineering/">L5 · 工程化与服务部署</a></td><td>流式 / 并发 / 限流 / 缓存 / 容器 / vLLM / 量化 / 成本</td></tr><tr><td>L6</td><td><a href="/learn/kb/l6-eval-observability/">L6 · 评测与可观测</a></td><td>评测集 / LLM-as-judge / Ragas / 回归门禁 / Trace / 线上监控</td></tr><tr><td>L7</td><td><a href="/learn/kb/l7-advanced/">L7 · 进阶方向</a></td><td>SFT / LoRA / QLoRA / DPO / GRPO / 蒸馏 / 推理优化 / VLM</td></tr></tbody></table><h2 id="六、来源与边界" tabindex="-1">六、来源与边界 <a class="header-anchor" href="#六、来源与边界" aria-label="Permalink to &quot;六、来源与边界&quot;">​</a></h2><ul><li><strong>主干来源</strong>：Datawhale 开源课程体系（hello-agents、happy-llm、tiny-universe、llm-universe、all-in-rag、self-llm、hugging-llm、wow-rag）</li><li><strong>补全来源</strong>：LangChain / LangGraph / MCP 规范 / Anthropic / Ragas / vLLM / Hugging Face / LLaMA-Factory / ms-swift / Dify / openai-cookbook 官方文档</li><li><strong>检索日期</strong>：2026-07-28（当日实抓，原始文件存 <code>_research/_raw/</code>）</li><li><strong>没检索到的</strong>：OpenAI 官方文档站（被 Cloudflare 403）→ 用 openai-cookbook 替代；huggingface.co 直连不可达 → 用 GitHub 源仓库的 <code>_toctree.yml</code></li><li><strong>不可依赖的</strong>：<code>llm-universe</code> 的 C7 剩下四节、<code>all-in-rag</code> 第十章在仓库里标着「规划中」，没有内容，本体系不依赖它们</li></ul><div class="warning custom-block"><p class="custom-block-title">关于时效性</p><p>模型版本号、API 参数默认值、榜单排名这类会变的东西，页面里凡涉及都<strong>标了检索日期</strong>。看的时候留意：超过半年的具体数字要重新核。</p></div>`,19)])])}const b=a(d,[["render",e]]);export{h as __pageData,b as default};
